<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import AppAlert from '../components/AppAlert.vue'
import ConfirmationModal from '../components/ConfirmationModal.vue'
import DataState from '../components/DataState.vue'
import { createDeviceCategory, deleteDeviceCategory, getDeviceCategories, updateDeviceCategory, type DeviceCategory } from '../services/deviceService'
import { authStore } from '../stores/authStore'
import { inventoryVisual } from '../utils/inventoryVisuals'

const categories = ref<DeviceCategory[]>([]); const loading = ref(true); const saving = ref(false); const errorMessage = ref(''); const successMessage = ref(''); const search = ref(''); const editing = ref<DeviceCategory | null>(null); const deleting = ref<DeviceCategory | null>(null)
const form = reactive({ name: '', description: '' })
const filtered = computed(() => { const q = search.value.toLocaleLowerCase('tr-TR').trim(); return categories.value.filter(item => !q || `${item.name} ${item.description ?? ''}`.toLocaleLowerCase('tr-TR').includes(q)) })
const totalDevices = computed(() => categories.value.reduce((total, item) => total + (item.deviceCount ?? 0), 0))
async function load() { loading.value = true; try { categories.value = await getDeviceCategories() } catch (error: unknown) { errorMessage.value = message(error, 'Kategoriler yüklenemedi.') } finally { loading.value = false } }
function startEdit(item: DeviceCategory) { editing.value = item; form.name = item.name; form.description = item.description ?? '' }
function resetForm() { editing.value = null; form.name = ''; form.description = '' }
async function save() { saving.value = true; errorMessage.value = ''; try { const payload = { name: form.name.trim(), description: form.description.trim() || null }; if (editing.value) await updateDeviceCategory(editing.value.id, payload); else await createDeviceCategory(payload); successMessage.value = editing.value ? 'Kategori güncellendi.' : 'Yeni kategori oluşturuldu.'; resetForm(); await load() } catch (error: unknown) { errorMessage.value = message(error, 'Kategori kaydedilemedi.') } finally { saving.value = false } }
async function confirmDelete() { if (!deleting.value) return; saving.value = true; try { await deleteDeviceCategory(deleting.value.id); successMessage.value = 'Kategori silindi.'; deleting.value = null; await load() } catch (error: unknown) { errorMessage.value = message(error, 'Kategori silinemedi.'); deleting.value = null } finally { saving.value = false } }
function message(error: unknown, fallback: string) { return error instanceof Error ? error.message : fallback }
onMounted(load)
</script>

<template><section class="inventory-manage-page"><header class="inventory-page-hero"><span class="inventory-page-hero__visual"><i class="bi bi-sliders"></i></span><div class="inventory-page-hero__main"><span class="inventory-page-hero__eyebrow">ENVANTER</span><h1 class="inventory-page-hero__title">Envanter Yönetimi</h1><p class="inventory-page-hero__description">Yeni kategori oluşturun; mevcut kategorileri görüntüleyin veya yeniden adlandırın.</p></div><div class="inventory-page-hero__count"><i class="bi bi-collection-fill"></i><div><strong>{{ categories.length }}</strong><span>aktif kategori</span></div></div></header><AppAlert v-if="successMessage" variant="success" dismissible @dismiss="successMessage = ''">{{ successMessage }}</AppAlert><AppAlert v-if="errorMessage" variant="danger" dismissible @dismiss="errorMessage = ''">{{ errorMessage }}</AppAlert><div class="inventory-manage-summary"><article><span><i class="bi bi-collection-fill"></i></span><div><strong>{{ categories.length }}</strong><small>Aktif kategori</small></div></article><article><span><i class="bi bi-box-seam-fill"></i></span><div><strong>{{ totalDevices }}</strong><small>Toplam cihaz</small></div></article><RouterLink to="/son-hareketler" class="inventory-manage-history"><i class="bi bi-clock-history"></i><span><strong>İşlem geçmişi</strong><small>Kategori ve envanter hareketleri</small></span><i class="bi bi-arrow-right"></i></RouterLink></div><div class="inventory-manage-grid"><section v-if="authStore.canEdit.value" class="dashboard-panel inventory-category-form"><div class="dashboard-panel__header"><div><span class="section-kicker">1. ADIM</span><h2>{{ editing ? 'Kategoriyi Düzenle' : 'Yeni Kategori Oluştur' }}</h2></div></div><form @submit.prevent="save"><label class="form-label" for="category-name">Kategori Adı</label><input id="category-name" v-model="form.name" class="form-control" required maxlength="100" placeholder="Örn: Projeksiyon"><label class="form-label mt-3" for="category-description">Açıklama</label><textarea id="category-description" v-model="form.description" class="form-control" rows="4" maxlength="500" placeholder="Opsiyonel açıklama"></textarea><div class="d-flex justify-content-end gap-2 mt-3"><button v-if="editing" type="button" class="btn btn-light border" @click="resetForm">İptal</button><button class="btn btn-primary" type="submit" :disabled="saving"><span v-if="saving" class="spinner-border spinner-border-sm me-1"></span><i v-else class="bi bi-folder-plus me-1"></i>{{ editing ? 'Değişiklikleri Kaydet' : 'Envanter Oluştur' }}</button></div></form></section><section class="dashboard-panel"><div class="dashboard-panel__header"><div><span class="section-kicker">2. ADIM</span><h2>Aktif Kategorileri Yönet</h2></div><span class="people-list-count">{{ filtered.length }} kategori</span></div><label class="search-box w-100 mb-3"><i class="bi bi-search"></i><span class="visually-hidden">Kategori ara</span><input v-model="search" class="form-control" type="search" placeholder="Kategori ara..."></label><DataState v-if="loading" type="loading" title="Kategoriler yükleniyor" /><DataState v-else-if="!filtered.length" type="no-results" title="Kategori bulunamadı" /><div v-else class="inventory-manage-list"><article v-for="item in filtered" :key="item.id" class="inventory-manage-row"><span class="inventory-manage-row__icon"><i :class="['bi', inventoryVisual(item.name).icon]"></i></span><div><strong>{{ item.name }}</strong><small>{{ item.deviceCount ?? 0 }} cihaz<template v-if="item.description"> · {{ item.description }}</template></small></div><div class="inventory-manage-row__actions"><RouterLink :to="{ name: 'inventories', query: { category: item.id } }" class="btn btn-sm btn-light border" title="Görüntüle"><i class="bi bi-eye"></i></RouterLink><button v-if="authStore.canEdit.value" class="btn btn-sm btn-warning" title="Düzenle" @click="startEdit(item)"><i class="bi bi-pencil-square"></i></button><button v-if="authStore.isAdmin.value" class="btn btn-sm btn-outline-danger" :disabled="Boolean(item.deviceCount)" :title="item.deviceCount ? 'İçinde cihaz bulunan kategori silinemez' : 'Sil'" @click="deleting = item"><i class="bi bi-trash3"></i></button></div></article></div></section></div><ConfirmationModal :show="Boolean(deleting)" title="Kategori silinsin mi?" message="Boş kategori sistemden kaldırılacaktır." :detail="deleting?.name ?? ''" :confirming="saving" :error-message="errorMessage" confirm-label="Kategoriyi Sil" @cancel="deleting = null" @confirm="confirmDelete" /></section></template>
